<?php
require_once __DIR__.'/includes/auth.php';
if(logged_in()) redirect(base_path('index.php'));
$page_title='Criar conta'; $tipo=($_GET['tipo']??$_POST['tipo']??'comprador')==='agricultor'?'agricultor':'comprador';$old=['name'=>'','email'=>'','phone'=>'','province'=>'Maputo','district'=>''];
if(is_post()) { verify_csrf($_POST['csrf']??'');foreach($old as $k=>$v)$old[$k]=trim((string)($_POST[$k]??$v));$name=$old['name'];$email=strtolower($old['email']);$phone=$old['phone'];$province=$old['province'];$district=$old['district'];$password=(string)($_POST['password']??'');$confirm=(string)($_POST['password_confirmation']??'');$tipo=($_POST['tipo']??'')==='agricultor'?'agricultor':'comprador';$accepted=!empty($_POST['accept_terms']);$errors=[];
  if(mb_strlen($name)<3||mb_strlen($name)>120)$errors[]='Indique o nome completo (3 a 120 caracteres).';
  if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>160)$errors[]='Indique um email válido.';
  if(!preg_match('/^\+?[0-9 ]{9,15}$/',$phone))$errors[]='Indique um telefone válido (ex.: +258 84 123 4567).';
  if($tipo==='agricultor'&&!in_array($province,provinces(),true))$errors[]='Selecione uma província válida.';
  if($tipo==='agricultor'&&mb_strlen($district)>100)$errors[]='Distrito demasiado longo.';
  if(!strong_password($password))$errors[]='Use uma password forte: mínimo 10 caracteres, com maiúscula, minúscula e número.';
  elseif($password!==$confirm)$errors[]='As passwords não coincidem.';
  if(!$accepted)$errors[]='Aceite os termos de utilização e a política de privacidade.';
  if($errors)flash('danger',implode(' ',$errors));
  else{try{$pdo=db();$pdo->beginTransaction();$role=$pdo->prepare('SELECT id FROM roles WHERE name=?');$role->execute([$tipo==='agricultor'?'farmer':'buyer']);$rid=$role->fetchColumn();$s=$pdo->prepare('INSERT INTO users(role_id,name,email,password,phone) VALUES(?,?,?,?,?)');$s->execute([$rid,$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone]);$uid=(int)$pdo->lastInsertId();if($tipo==='agricultor'){$s=$pdo->prepare('INSERT INTO farmers(user_id,province,district,verification_status) VALUES(?,?,?,"pending")');$s->execute([$uid,$province,$district!==''?$district:null]);}else{$pdo->prepare('INSERT INTO buyers(user_id) VALUES(?)')->execute([$uid]);}$pdo->prepare('INSERT INTO legal_acceptances(user_id,document_type,version,ip) VALUES(?,"terms","1.0",?),(?,"privacy","1.0",?)')->execute([$uid,client_ip(),$uid,client_ip()]);$pdo->prepare('INSERT IGNORE INTO notification_preferences(user_id) VALUES(?)')->execute([$uid]);
    if($tipo==='agricultor'){$admins=$pdo->query("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='superadmin' AND u.status='active'")->fetchAll(PDO::FETCH_COLUMN);foreach($admins as $aid)notify((int)$aid,'Novo agricultor por verificar',$name.' ('.$email.') registou-se como agricultor e aguarda verificação.');}
    $pdo->commit();audit($uid,'register','auth','Novo cadastro de '.$tipo);flash('success','Conta criada com sucesso. Já pode iniciar sessão.');redirect(base_path('login.php'));}catch(PDOException $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('danger',$e->getCode()==='23000'?'Este email já está registado.':'Não foi possível criar a conta.');}}}
include __DIR__.'/includes/header.php';?><section class="auth-section"><div class="auth-card auth-card-wide"><div class="text-center mb-4"><div class="auth-logo"><i class="bi bi-leaf"></i></div><h1>Crie a sua conta</h1><p class="text-muted">Junte-se ao comércio agrícola local.</p></div><div class="role-switch mb-4"><a class="<?=$tipo==='comprador'?'active':''?>" href="?tipo=comprador"><i class="bi bi-bag me-2"></i>Quero comprar</a><a class="<?=$tipo==='agricultor'?'active':''?>" href="?tipo=agricultor"><i class="bi bi-sun me-2"></i>Quero vender</a></div><form method="post"><?=csrf_field()?><input type="hidden" name="tipo" value="<?=e($tipo)?>"><div class="row g-3"><div class="col-md-6"><label class="form-label" for="cd-name">Nome completo</label><input id="cd-name" name="name" class="form-control" minlength="3" maxlength="120" value="<?=e($old['name'])?>" required></div><div class="col-md-6"><label class="form-label" for="cd-phone">Telefone</label><input id="cd-phone" name="phone" class="form-control" maxlength="20" placeholder="+258 8x xxx xxxx" value="<?=e($old['phone'])?>" required></div><div class="col-12"><label class="form-label" for="cd-email">Email</label><input id="cd-email" type="email" name="email" class="form-control" maxlength="160" value="<?=e($old['email'])?>" required></div><?php if($tipo==='agricultor'): ?><div class="col-md-6"><label class="form-label" for="cd-province">Província</label><select id="cd-province" name="province" class="form-select"><?php foreach(provinces() as $pv): ?><option value="<?=e($pv)?>" <?=$old['province']===$pv?'selected':''?>><?=e($pv)?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label" for="cd-district">Distrito</label><input id="cd-district" name="district" class="form-control" maxlength="100" placeholder="Ex.: Boane" value="<?=e($old['district'])?>"></div><?php endif; ?><div class="col-md-6"><label class="form-label" for="cd-password">Password</label><input id="cd-password" type="password" name="password" class="form-control" minlength="10" required autocomplete="new-password"><div class="form-text">Mínimo 10 caracteres, com maiúscula, minúscula e número.</div></div><div class="col-md-6"><label class="form-label" for="cd-password2">Confirmar password</label><input id="cd-password2" type="password" name="password_confirmation" class="form-control" minlength="10" required autocomplete="new-password"></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="accept_terms" id="accept_terms" required><label class="form-check-label small" for="accept_terms">Aceito os <a href="<?=base_path('termos.php')?>" target="_blank">Termos de utilização</a> e a <a href="<?=base_path('privacidade.php')?>" target="_blank">Política de privacidade</a>.</label></div></div><div class="col-12"><button class="btn btn-primary btn-lg w-100">Criar conta <i class="bi bi-arrow-right ms-2"></i></button></div></div></form><p class="text-center text-muted mt-4 mb-0">Já tem conta? <a href="<?=base_path('login.php')?>">Entrar</a></p></div></section><?php include __DIR__.'/includes/footer.php'; ?>
